<script lang="ts">
  import { Archive, ArrowLeft, LayoutGrid, ListFilter, Plus, Search } from "@lucide/svelte";
  import { t } from "./i18n";
  import { providerDisplayName } from "./provider-display";
  import CollaborationBoardCardView from "./CollaborationBoardCard.svelte";
  import CollaborationBoardDetail from "./CollaborationBoardDetail.svelte";
  import CollaborationBoardEditor from "./CollaborationBoardEditor.svelte";
  import { COLLABORATION_BOARD_PRIORITIES, COLLABORATION_BOARD_STATUSES, archiveBoardCard, boardDefaultRoles, cardSearchText, createBoardCard, getBoardCard, listBoardCards, normalizeBoardRole, updateBoardCard, type BoardApi, type CollaborationBoardAttachCandidate, type CollaborationBoardCard, type CollaborationBoardDraft, type CollaborationBoardExecutionConfig } from "./collaboration-board";
  export let api:BoardApi;
  export let workspaces:Array<{id:string;displayName:string}>=[];
  export let executionConfig:CollaborationBoardExecutionConfig;
  export let sessionCandidates:CollaborationBoardAttachCandidate[]=[];
  export let initialCardId:string|null=null;
  export let onclose:()=>void=()=>{};
  export let onopensession:(kind:"task"|"collaboration",id:string)=>void=()=>{};
  export let onaction:()=>void|Promise<void>=()=>{};
  export let oncardschange:(ids:string[])=>void=()=>{};
  let cards:CollaborationBoardCard[]=[];let loading=true;let error="";let search="";let status="";let priority="";let workspace="";let provider="";let includeArchived=false;let editor=false;let editing:CollaborationBoardCard|null=null;let saving=false;let selected:CollaborationBoardCard|null=null;let mobileStatus="queued";
  const COLUMN_LIMIT=6;
  let expanded:Record<string,boolean>={};let cleaning=false;
  async function archiveCompleted(){
    const targets=cards.filter(card=>card.boardStatus==="completed"&&!card.archivedAt);
    if(cleaning||!targets.length||!confirm($t("collaborationBoard.archiveCompletedConfirm",{count:targets.length})))return;
    cleaning=true;error="";
    try{for(const card of targets){const next=await archiveBoardCard(api,card);cards=includeArchived?cards.map(item=>item.id===next.id?next:item):cards.filter(item=>item.id!==next.id)}}
    catch(value){error=value instanceof Error?value.message:String(value)}
    finally{cleaning=false}
  }
  const workspaceName=(id?:string|null)=>workspaces.find(item=>item.id===id)?.displayName??"";
  async function load(){loading=true;error="";try{cards=await listBoardCards(api,includeArchived);if(!cards.some(card=>card.boardStatus===mobileStatus))mobileStatus=COLLABORATION_BOARD_STATUSES.find(value=>cards.some(card=>card.boardStatus===value))??"queued";if(initialCardId&&!selected)selected=await getBoardCard(api,initialCardId)}catch(value){error=value instanceof Error?value.message:String(value)}finally{loading=false}}
  async function open(card:CollaborationBoardCard){try{selected=await getBoardCard(api,card.id)}catch{selected=card}}
  function draft(card?:CollaborationBoardCard|null):CollaborationBoardDraft{return card?{title:card.title,description:card.description,boardStatus:card.boardStatus,priority:card.priority,workspaceId:card.workspaceId??null,targetBranch:card.targetBranch??"",roles:Object.fromEntries(Object.entries(card.roles).map(([key,role])=>[key,role?normalizeBoardRole(executionConfig,role):role]))}:{title:"",description:"",boardStatus:"queued",priority:"normal",workspaceId:workspaces[0]?.id??null,targetBranch:"",roles:boardDefaultRoles(executionConfig)}}
  async function save(value:CollaborationBoardDraft){saving=true;error="";try{const card=editing?await updateBoardCard(api,editing,value):await createBoardCard(api,value);cards=editing?cards.map(item=>item.id===card.id?card:item):[card,...cards];selected=card;editor=false;editing=null}catch(value){error=value instanceof Error?value.message:String(value)}finally{saving=false}}
  function changed(card:CollaborationBoardCard){cards=card.archivedAt&&!includeArchived?cards.filter(item=>item.id!==card.id):cards.map(item=>item.id===card.id?card:item);selected=card}
  $: filtered=cards.filter(card=>(!status||card.boardStatus===status)&&(!priority||card.priority===priority)&&(!workspace||card.workspaceId===workspace)&&(!provider||Object.values(card.roles).some(role=>role?.provider===provider))&&(!search.trim()||cardSearchText(card,workspaceName(card.workspaceId)).includes(search.trim().toLocaleLowerCase())));
  $: columns=COLLABORATION_BOARD_STATUSES.map(value=>{const list=filtered.filter(card=>card.boardStatus===value);return {value,total:list.length,visible:expanded[value]?list:list.slice(0,COLUMN_LIMIT),hidden:Math.max(0,list.length-COLUMN_LIMIT)}});
  $: completedCount=cards.filter(card=>card.boardStatus==="completed"&&!card.archivedAt).length;
  $: oncardschange(cards.filter(card=>!card.archivedAt).map(card=>card.id));
  $: void includeArchived,load();
</script>

{#if selected}
  <CollaborationBoardDetail {api} {executionConfig} {sessionCandidates} card={selected} workspaceName={workspaceName(selected.workspaceId)} onback={()=>selected=null} onedit={(card)=>{editing=card;editor=true}} onchanged={changed} {onaction} {onopensession}/>
{:else}
  <main class="board-page">
    <header class="page-header"><button class="board-back" type="button" onclick={onclose}><ArrowLeft size={18}/>{$t("common.back")}</button><div><span>{$t("collaborationBoard.kicker")}</span><h1>{$t("collaborationBoard.title")}</h1><p>{$t("collaborationBoard.description")}</p></div><button class="board-new" type="button" onclick={()=>{editing=null;editor=true}}><Plus size={17}/>{$t("collaborationBoard.newCard")}</button></header>
    <div class="board-toolbar"><label class="board-search"><Search size={17}/><input aria-label={$t("common.search")} placeholder={$t("collaborationBoard.searchPlaceholder")} bind:value={search}/></label><div class="board-filters"><label><span>{$t("common.status")}</span><select aria-label={$t("common.status")} bind:value={status}><option value="">{$t("common.all")}</option>{#each COLLABORATION_BOARD_STATUSES as value}<option {value}>{$t(`collaborationBoard.status.${value}`)}</option>{/each}</select></label><label><span>{$t("collaborationBoard.field.priority")}</span><select aria-label={$t("collaborationBoard.field.priority")} bind:value={priority}><option value="">{$t("common.all")}</option>{#each COLLABORATION_BOARD_PRIORITIES as value}<option {value}>{$t(`collaborationBoard.priority.${value}`)}</option>{/each}</select></label><label><span>{$t("workspace.label")}</span><select aria-label={$t("workspace.label")} bind:value={workspace}><option value="">{$t("common.all")}</option>{#each workspaces as item}<option value={item.id}>{item.displayName}</option>{/each}</select></label><label><span>{$t("session.provider")}</span><select aria-label={$t("session.provider")} bind:value={provider}><option value="">{$t("common.all")}</option>{#each executionConfig.providers as item}<option value={item.provider}>{providerDisplayName(item.provider)}</option>{/each}</select></label><button class:active={includeArchived} class="board-archive" onclick={()=>includeArchived=!includeArchived}><Archive size={15}/>{$t("collaborationBoard.archived")}</button></div></div>
    {#if loading}<div class="board-page-empty">{$t("task.loading")}</div>{:else if error}<div class="board-page-empty error" role="alert">{error}</div>{:else}
      {#if !filtered.length}<section class="board-empty"><span><LayoutGrid size={28}/></span><div><h2>{$t("collaborationBoard.empty")}</h2><p>{$t("collaborationBoard.quickCreateBody")}</p></div><button class="board-new" type="button" onclick={()=>{editing=null;editor=true}}><Plus size={17}/>{$t("collaborationBoard.newCard")}</button></section>{:else}<nav class="mobile-status" aria-label={$t("common.status")}>{#each columns as column}<button class:active={mobileStatus===column.value} onclick={()=>mobileStatus=column.value}>{$t(`collaborationBoard.status.${column.value}`)} <small>{column.total}</small></button>{/each}</nav>
      <div class="kanban"><span class="view-label"><LayoutGrid size={16}/>{$t("collaborationBoard.boardView")}</span>{#each columns as column}<section class="column" class:mobile-hidden={mobileStatus!==column.value}><header><strong>{$t(`collaborationBoard.status.${column.value}`)}</strong>{#if column.value==="completed"&&completedCount}<button class="column-clean" type="button" disabled={cleaning} onclick={archiveCompleted}><Archive size={13}/>{$t("collaborationBoard.archiveCompleted")}</button>{/if}<span>{column.total}</span></header><div>{#each column.visible as card (card.id)}<CollaborationBoardCardView {card} workspaceName={workspaceName(card.workspaceId)} onopen={open}/>{:else}<p>{$t("collaborationBoard.emptyColumn")}</p>{/each}</div>{#if column.hidden}<button class="column-more" type="button" onclick={()=>expanded={...expanded,[column.value]:!expanded[column.value]}}>{expanded[column.value]?$t("collaborationBoard.showLess"):$t("collaborationBoard.showMore",{count:column.hidden})}</button>{/if}</section>{/each}</div>{/if}
    {/if}
  </main>
{/if}
{#if editor}<CollaborationBoardEditor initial={draft(editing)} {workspaces} {executionConfig} {saving} {error} onsave={save} onclose={()=>{editor=false;editing=null;error=""}}/>{/if}

<style>
  .board-page{width:min(var(--page-max),100%);margin:0 auto;padding:28px clamp(14px,2.4vw,28px) 110px}.page-header{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:start;gap:14px}.page-header>div>span{color:var(--accent-strong);font-size:.68rem;font-weight:850;letter-spacing:.1em}.page-header h1{margin:4px 0 6px;font-size:clamp(1.65rem,3vw,2.15rem);letter-spacing:-.035em}.page-header p{margin:0;color:var(--muted);font-size:.86rem}.board-back,.board-new,.board-archive{display:flex;align-items:center;justify-content:center;gap:6px;min-height:42px;padding:0 13px;border:1px solid var(--line);border-radius:var(--radius-control-lg);background:var(--surface);color:var(--text);font-size:.78rem;font-weight:750}.board-back{margin-left:-8px;border:0;background:transparent}.board-new{border-color:transparent;background:var(--accent);color:var(--on-accent);box-shadow:var(--shadow)}.board-toolbar{display:grid;grid-template-columns:minmax(260px,.85fr) minmax(0,1.7fr);gap:10px;margin:24px 0 16px;padding:10px;border:1px solid var(--line);border-radius:16px;background:var(--surface);box-shadow:0 3px 14px var(--overlay-weak)}.board-toolbar .board-search{display:flex;align-items:center;gap:8px;min-width:0;padding:0 12px;border:1px solid var(--line);border-radius:11px;background:var(--bg);color:var(--muted)}.board-toolbar .board-search input{width:100%;min-height:44px;border:0;outline:0;background:transparent;color:var(--text)}.board-filters{display:grid;grid-template-columns:repeat(4,minmax(110px,1fr)) auto;gap:7px}.board-filters label{display:grid;min-width:0;gap:1px;padding:5px 9px;border:1px solid transparent;border-radius:10px;background:var(--surface-2)}.board-filters label>span{color:var(--muted);font-size:.58rem;font-weight:750}.board-filters select{width:100%;min-width:0;border:0;outline:0;background:transparent;color:var(--text);font-size:.73rem;font-weight:700}.board-archive{min-width:42px;padding-inline:10px;background:var(--surface-2)}.board-archive.active{color:var(--accent);border-color:var(--accent)}.board-empty{min-height:310px;display:grid;place-items:center;align-content:center;gap:12px;padding:34px;border:1px dashed var(--line-strong);border-radius:22px;background:color-mix(in srgb,var(--surface) 68%,transparent);text-align:center}.board-empty>span{display:grid;width:58px;height:58px;place-items:center;border-radius:18px;background:var(--accent-soft);color:var(--accent)}.board-empty h2{margin:0;font-size:1rem}.board-empty p{margin:5px 0 0;color:var(--muted);font-size:.76rem}.board-empty .board-new{margin-top:5px}.kanban{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,235px),1fr));gap:10px;align-items:start;padding-bottom:8px}.view-label{display:none}.column{min-width:0;padding:10px;border:1px solid color-mix(in srgb,var(--line) 82%,transparent);border-radius:16px;background:color-mix(in srgb,var(--surface-2) 58%,transparent)}.column>header{display:flex;align-items:center;justify-content:space-between;padding:3px 3px 11px}.column>header strong{font-size:.74rem}.column>header span{display:grid;min-width:23px;height:23px;place-items:center;border-radius:999px;background:var(--surface);color:var(--muted);font-size:.65rem}.column>header .column-clean{display:flex;align-items:center;gap:4px;margin-right:auto;margin-left:8px;padding:3px 8px;border:1px solid var(--line);border-radius:999px;background:var(--surface);color:var(--muted);font-size:.6rem;font-weight:750}.column>header .column-clean:disabled{opacity:.55}.column-more{display:flex;align-items:center;justify-content:center;width:100%;margin-top:9px;padding:7px 9px;border:1px solid var(--line);border-radius:10px;background:var(--surface);color:var(--muted);font-size:.66rem;font-weight:750}.column>div{display:grid;gap:9px}.column>div>p{padding:14px 10px;text-align:center;color:var(--muted);font-size:.68rem}.board-page-empty{padding:30px 10px;text-align:center;color:var(--muted);font-size:.68rem}.error{color:var(--danger)}.mobile-status{display:none}@media(max-width:1100px) and (min-width:801px){.board-toolbar{grid-template-columns:1fr}}@media(max-width:800px){.board-page{padding-top:18px}.page-header{grid-template-columns:auto 1fr}.page-header .board-new{grid-column:2;justify-self:start}.page-header p{font-size:.75rem}.board-toolbar{grid-template-columns:1fr;padding:8px}.board-filters{grid-template-columns:1fr 1fr}.board-archive{min-height:42px}.mobile-status{display:flex;gap:6px;overflow-x:auto;margin-bottom:10px;padding-bottom:4px;scrollbar-width:none}.mobile-status button{display:flex;gap:6px;white-space:nowrap;padding:8px 10px;border:1px solid var(--line);border-radius:999px;background:var(--surface);font-size:.7rem}.mobile-status button.active{color:var(--accent);border-color:var(--accent);background:var(--accent-soft)}.kanban{display:block;overflow:visible}.column.mobile-hidden{display:none}.column{padding:0;background:transparent;border:0}.column>header{display:none}.column>header:has(.column-clean){display:flex;justify-content:flex-end;padding:0 0 8px}.column>header:has(.column-clean) strong,.column>header:has(.column-clean)>span{display:none}.column>header .column-clean{margin:0}.board-empty{min-height:250px}}@media(max-width:420px){.board-filters{grid-template-columns:1fr}.page-header{gap:8px}.board-back{padding-inline:2px;font-size:0}.page-header .board-new{grid-column:1/-1;justify-self:stretch}.board-empty{padding:24px 16px}}
</style>
